public class ReverseString {

    // Approach 1: StringBuilder built-in — preferred
    static String reverseBuiltin(String s) {
        return new StringBuilder(s).reverse().toString();
    }

    // Approach 2: Loop from end
    static String reverseLoop(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = s.length() - 1; i >= 0; i--) {
            sb.append(s.charAt(i));
        }
        return sb.toString();
    }

    // Approach 3: char array swap — O(1) extra space
    static String reverseSwap(String s) {
        char[] chars = s.toCharArray();
        int left = 0, right = chars.length - 1;
        while (left < right) {
            char temp = chars[left];
            chars[left] = chars[right];
            chars[right] = temp;
            left++;
            right--;
        }
        return new String(chars);
    }

    public static void main(String[] args) {
        System.out.println(reverseBuiltin("hello"));  // olleh
        System.out.println(reverseLoop("hello"));     // olleh
        System.out.println(reverseSwap("hello"));     // olleh

        // Palindrome check — compare string to its reverse
        String word = "racecar";
        boolean isPalindrome = word.equals(reverseBuiltin(word));
        System.out.println(isPalindrome); // true
    }
}
