import java.util.HashMap;
import java.util.Map;

public class CharFrequency {
    public static void main(String[] args) {

        // Approach 1: HashMap — works for any characters
        String s = "programming";
        Map<Character, Integer> freq = new HashMap<>();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            freq.put(c, freq.getOrDefault(c, 0) + 1);
        }
        System.out.println(freq);
        // {p=1, r=2, o=1, g=2, a=1, m=2, i=1, n=1}

        // Approach 2: int[26] — faster for lowercase-only strings
        int[] count = new int[26];
        for (char c : s.toCharArray()) {
            count[c - 'a']++; // 'a'=0, 'b'=1, ..., 'z'=25
        }
        for (int i = 0; i < 26; i++) {
            if (count[i] > 0) {
                System.out.println((char)('a' + i) + ": " + count[i]);
            }
        }
        // a: 1, g: 2, i: 1, m: 2, n: 1, o: 1, p: 1, r: 2

        // Anagram check — two strings are anagrams if their frequency maps are equal
        System.out.println(isAnagram("listen", "silent")); // true
    }

    static boolean isAnagram(String a, String b) {
        if (a.length() != b.length()) return false;
        int[] count = new int[26];
        for (char c : a.toCharArray()) count[c - 'a']++;
        for (char c : b.toCharArray()) count[c - 'a']--;
        for (int n : count) if (n != 0) return false;
        return true;
    }
}
