import java.util.Arrays;

public class AnagramCheck {

    // Approach 1: Sort and compare — O(n log n)
    static boolean isAnagramSort(String s1, String s2) {
        if (s1.length() != s2.length()) return false;
        char[] a = s1.toCharArray();
        char[] b = s2.toCharArray();
        Arrays.sort(a);
        Arrays.sort(b);
        return Arrays.equals(a, b);
    }

    // Approach 2: Frequency counter — O(n), O(1) space
    static boolean isAnagramFreq(String s1, String s2) {
        if (s1.length() != s2.length()) return false;
        int[] count = new int[26];
        for (char c : s1.toCharArray()) count[c - 'a']++;
        for (char c : s2.toCharArray()) count[c - 'a']--;
        for (int n : count) if (n != 0) return false;
        return true;
    }

    public static void main(String[] args) {
        System.out.println(isAnagramSort("listen", "silent"));   // true
        System.out.println(isAnagramFreq("listen", "silent"));   // true

        System.out.println(isAnagramSort("hello", "world"));     // false
        System.out.println(isAnagramFreq("aab", "abb"));         // false — same letters, different counts
    }
}
